import type { FieldContact } from "@/lib/field/types";

/**
 * Media brief for a prospect's site: the Higgsfield B-roll shots (generated by
 * whoever runs the brief, through the Higgsfield connector) and the optional
 * HeyGen spokesperson video. File names match the template's SITE config defaults,
 * so dropping the downloads into /assets needs no code change.
 */

/** House style every Higgsfield shot uses. */
export const HIGGSFIELD_STYLE =
  "Architectural Digest aesthetic, golden hour lighting, deep dynamic range, shallow depth of field";
export const CAMERA_MOVES = ["slow tracking forward", "orbital pan", "smooth dolly-in"] as const;
export type CameraMove = (typeof CAMERA_MOVES)[number];

export type SceneKind = "kitchen" | "pool" | "restaurant" | "home" | "general";

const SCENES: Record<SceneKind, { subject: string; camera: CameraMove }> = {
  kitchen: {
    subject: "A newly finished high-end custom kitchen: large island with a waterfall stone counter, warm wood and painted cabinetry, brass fixtures, pendant lights, sunlight raking across the counters",
    camera: "smooth dolly-in",
  },
  pool: {
    subject: "A modern architectural backyard pool with clean stone coping, glassy still water, an outdoor living area and landscape lighting just switching on",
    camera: "orbital pan",
  },
  restaurant: {
    subject: "The restaurant's signature dish being plated, steam rising, then the warm dining room behind it softly out of focus",
    camera: "slow tracking forward",
  },
  home: {
    subject: "The exterior of a beautifully finished upscale home and front walkway, the result of the client's work, with nobody in frame",
    camera: "slow tracking forward",
  },
  general: {
    subject: "The finished result of the business's work in its best setting, clean and aspirational, with nobody looking into the lens",
    camera: "smooth dolly-in",
  },
};

// First match wins, so restaurant comes before kitchen ("Kitchen & Bar").
const KINDS: [SceneKind, RegExp][] = [
  ["restaurant", /restaurant|grill|cafe|café|diner|bistro|kitchen &? bar|pizza|taco|burger|bbq|barbecue|gyro|sushi|bakery|food truck|catering|smoothie|slider/i],
  ["kitchen", /kitchen|cabinet|countertop|remodel|renovat|bath(room)?\b/i],
  ["pool", /\bpools?\b|spa builder|backyard|hardscap|patio/i],
  ["home", /roof|siding|window|landscap|paint|builder|construction|contractor|hvac|plumb|electric|fence|concrete/i],
];

/** Picks the B-roll scene from what we know about the business. */
export function sceneKind(text: string): SceneKind {
  return KINDS.find(([, re]) => re.test(text))?.[0] ?? "general";
}

export interface MediaAnswers {
  spokesperson_script?: string;
  heygen_avatar_id?: string;
}

const words = (s: string) => s.trim().split(/\s+/).filter(Boolean).length;

export function mediaBrief(c: FieldContact, about: string, a: MediaAnswers = {}) {
  const kind = sceneKind(`${c.name} ${about} ${c.notes ?? ""}`);
  const scene = SCENES[kind];
  const prompt =
    `${scene.subject}. Camera: one continuous ${scene.camera}, slow and steady, no cuts. ` +
    `${HIGGSFIELD_STYLE}. Photoreal, no text, no logos, no faces looking into the lens. ` +
    `Start and end on nearly the same framing so the clip loops seamlessly.`;

  const script = a.spokesperson_script?.trim() || "";
  const scriptWords = words(script);
  const wantsSpokesperson = Boolean(script || a.heygen_avatar_id?.trim());
  const portrait = kind === "restaurant";

  return {
    scene: kind,
    higgsfield: {
      style: HIGGSFIELD_STYLE,
      shots: [
        {
          id: "hero",
          prompt,
          camera: scene.camera,
          aspect_ratio: "16:9",
          duration_sec: 10,
          resolution: "1080p minimum, 4K when offered",
          audio: "none (muted)",
          raw_file: "assets/raw/hero.mp4",
        },
      ],
      steps: [
        "Generate each shot with the Higgsfield connector (Cinema Studio or the commercial generator), using the shot's prompt and the matching camera preset.",
        "Poll until it finishes, then download the highest-resolution MP4 to the site's raw_file path.",
        "From the site folder run: scripts/prepare-video.sh assets/raw/hero.mp4 hero --loop --mobile",
        "That writes assets/hero.mp4, hero.webm, hero-poster.jpg and hero-mobile.mp4, which SITE.hero.video already points at.",
      ],
    },
    heygen: {
      enabled: wantsSpokesperson,
      suggested: !wantsSpokesperson && kind === "restaurant",
      avatar: a.heygen_avatar_id?.trim() || "preset spokesperson (pick a HeyGen stock avatar that fits the brand)",
      script: script || null,
      script_words: scriptWords,
      script_check: !script ? "No script yet: write 30–60 seconds, about 75–150 words." : scriptWords < 60 ? "Short: aim for 75–150 words (30–60 seconds)." : scriptWords > 170 ? "Long: cut to 150 words or fewer (60 seconds)." : "ok",
      orientation: portrait ? "portrait 9:16" : "landscape 16:9",
      captions: true,
      raw_file: "assets/raw/spokesperson.mp4",
      steps: [
        "Generate with the HeyGen API or connector: the owner's avatar ID (or the preset), this script, captions on.",
        "Download the MP4 and the captions file (.vtt) when it finishes.",
        "From the site folder run: scripts/prepare-video.sh assets/raw/spokesperson.mp4 spokesperson --keep-audio",
        `Copy the captions to assets/spokesperson.vtt, then set SITE.spokesperson.enabled = true, captions = "assets/spokesperson.vtt", orientation = "${portrait ? "portrait" : "landscape"}".`,
      ],
    },
  };
}
